.lst-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lst-root,.lst-root *,.lst-root *::before,.lst-root *::after{box-sizing:border-box}
.lst-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lst-root img{display:block;border:0;max-width:none}
.lst-root [hidden]{display:none!important}
.lst-root .nS4_124_1465{position:absolute;align-content:stretch;display:flex;flex-direction:column;align-items:center;left:0;top:19px}
.lst-root .nS4_124_1466{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;line-height:0;place-items:start;position:relative;flex-shrink:0}
.lst-root .nS4_124_1467{grid-column:1;height:34px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:81.9px}
.lst-root .x400031{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lst-root .nS4_124_1470{word-break:break-word;grid-column:1;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:17px;margin-left:14.9px;margin-top:6px;font-style:normal;position:relative;grid-row:1;font-size:14px;text-align:center;color:var(--wa-text, #fff);white-space:nowrap;width:54px}
.lst-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lst-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
